INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033623', 'Godzilla Minus Zero', 'godzilla-minus-zero', 'B', 'CIENCIA FICCIÓN', 135, 'GODZILLA MINUS ZERO retoma la historia en 1949, dos años después de los turbulentos acontecimientos de Godzilla Minus One, y continúa la historia de la familia Shikishima mientras enfrentan una nueva catástrofe. Como proyecto filmado para IMAX, GODZILLA MINUS ZERO fue filmada con cámaras digitales de alta definición certificadas por IMAX y optimizada en sonido e imagen de manera única para pantallas IMAX. Los fans podrán ver a Godzilla llevado a nuevas y terroríficas alturas, haciendo de GODZILLA MINUS ZERO un verdadero evento cinematográfico imperdible.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Poster_720x1022_Godzilla_5ago1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Header_movie_1440x900_Still_Godzilla_5ago_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/6a7ccff3283f2-godzilla-minus-zero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033794', 'El Gato Con Sombrero', 'el-gato-con-sombrero', 'A', 'COMEDIA, ANIMACIÓN', 115, '"¡Conoce a El Gato Con Sombrero como nunca antes lo habías visto! Fiel a la maravillosa y extravagante tradición de Dr. Seuss, El Gato Con Sombrero llega por primera vez a la pantalla grande en su debut cinematográfico animado, con una nueva y épica aventura cargada de irreverencia, donde reinan el caos, la magia y las travesuras. Haciendo lo que mejor sabe hacer, el Gato —con la voz de Bill Hader en su versión original— llena de alegría a los niños con su característico y singular sentido del humor, llevándolos a ellos y al público a un viaje fantástico por un mundo que jamás imaginaron. En la película, nuestro héroe se enfrenta a su misión más difícil hasta ahora para el I.I.I.I. (Instituto para la Institución de la Imaginación e Inspiración, S.A.): animar a Gabby y Sebastián, dos hermanos que están teniendo dificultades para adaptarse a su nueva ciudad. Conocido por siempre llevar las cosas al extremo, esta podría ser la última oportunidad de este agente del caos para demostrar su valía... o perder su sombrero mágico."', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/P_720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/Header_movie_details_B_1440X900_3.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/6adbac5a8e133-el-gato-con-sombrero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033222', 'La Venganza Del Charro Negro', 'la-venganza-del-charro-negro', 'A', 'ANIMACIÓN', 85, 'Después de varios años, el temible Charro Negro regresa con un nuevo propósito: vengarse de Leo San Juan y cobrar una deuda que ha quedado pendiente. Para lograrlo, liberará a algunas de las criaturas y leyendas sobrenaturales que Leo ha enfrentado a lo largo de sus aventuras, obligándolo a reencontrarse con sus antiguos enemigos. Pero esta vez, el Charro Negro tiene un objetivo mucho más personal: su hermano, Nando. Mientras las leyendas se desatan y el peligro crece, Leo deberá proteger a su hermano y reunir nuevamente a sus amigos para descubrir el verdadero plan del Charro Negro. En una aventura que llevará al grupo al límite, Leo tendrá que enfrentarse una vez más a las criaturas de su pasado y descubrir que, para derrotar al Charro Negro, no solo tendrá que demostrar su valentía, sino luchar por aquello que más quiere.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/720x1022_copia_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/1440x900_69.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/6aa88358db4b3-la-vengaza-del-charro-negro.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033355', 'El Bosque Salvaje: Wildwood', 'el-bosque-salvaje-wildwood', 'B', 'ANIMACIÓN', 132, 'Después de que su pequeño hermano es secuestrado por una parvada de cuervos, la audaz adolescente, Prue, inicia una desesperada misión de rescate hacia el Bosque Salvaje acompañada únicamente por su torpe pero leal compañero de clase, Curtis. Prue navega por un mundo de animales parlantes, bandidos y poderosas figuras impulsadas por el duelo y la ambición. Mientras los amigos se ven arrastrados a un conflicto que amenaza el equilibrio del bosque mismo, Prue debe descubrir la fuerza y la fe que nunca supo que poseía. Si quiere salvar a su hermano y proteger el frágil futuro de Wildwood, tendrá que arriesgarlo todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Wildwood_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Header_movie_details_1440x900__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/6ab4000547426-wildwood.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033517', 'Clayface', 'clayface', 'C', 'TERROR, THRILLER', 108, 'De DC Studios, “Clayface” es un thriller de terror dirigido por James Watkins, protagonizado por Tom Rhys Harries en el papel principal del icónico villano favorito de culto de la galería de villanos de Gotham. El meteórico ascenso de Matt Hagen, de joven de las calles de Gotham a estrella de Hollywood, se ve trágicamente truncado cuando las acciones de un jefe del crimen local lo dejan horriblemente desfigurado. Abandonado por quienes lo rodean y sin nada que perder, Matt recurre a un tratamiento de vanguardia que milagrosamente le devuelve su apariencia anterior... pero que también altera de forma inesperada su percepción de la realidad, precipitándolo por un camino destructivo de venganza desmedida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/P_720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/HMD_1440X900_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/6abd9302c9bb2-clayface.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033736', 'Ceniza En La Boca', 'ceniza-en-la-boca', 'B15', 'DRAMA', 102, 'En busca de una vida mejor, Lucila viaja con su hermano Diego desde México para encontrarse con su madre en Madrid, quien lleva ahí ocho años trabajando ilegalmente para mantenerlos. Al llegar, la vida que los espera resulta más dura de lo que imaginaban.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/CEB_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/CEB_Header_movie_details1440x900_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/6acff3c21954e-ceniza-boca.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033862', 'Klara Y El Sol', 'klara-y-el-sol', 'B', 'COMEDIA, DRAMA', 116, 'Basada en la exitosa novela del premio Nobel Kazuo Ishiguro y escrita y dirigida por el ganador del premio Óscar® Taika Waititi (Jojo Rabbit), Klara y el Sol presenta al público a Klara (Jenna Ortega), una Amiga Artificial que solo desea encontrar el hogar perfecto. Cuando Klara conoce a Josie (Mia Tharia), ambas sienten de inmediato una conexión especial. Josie tiene una relación tensa con su madre (Amy Adams) y han sufrido grandes pérdidas, pero la inocencia y la lealtad inquebrantable de Klara comienzan a sanar a la familia e iluminar el complejo mundo de Josie', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/SMBND_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/KATS_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/6aa879abaa225-klara-y-el-sol.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033667', 'Caballo Salvaje Nueve', 'caballo-salvaje-nueve', 'C', 'DRAMA, THRILLER, CRIMEN', 116, 'Poco antes del golpe de Estado chileno de 1973, los agentes de la CIA Chris (John Malkovich) y Lee (Sam Rockwell) son enviados desde Santiago a la Isla de Pascua por su jefe, MJ (Steve Buscemi). Entre las icónicas estatuas de la isla, y mientras los socios de larga data lidian con sus pasados oscuros y conspiraciones presentes, el nuevo vínculo de Chris con unas estudiantes rebeldes (Mariana di Girolamo y Ailín Salas) pone en riesgo el curso del viaje en este paraíso remoto.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/14_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/6ac67c0b5a1c5-caballo-salvaje-nueve.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033679', 'La Venus Eléctrica', 'la-venus-electrica', 'B', 'COMEDIA', 122, 'París, 1928. Un joven pintor en augue, Antoine Balestro, no ha podido pintar desde la muerte de su esposa, para desgracia de su representante, Armand. Una noche de borrachera, Antoine intenta contactar con su esposa a través de una vidente; Suzanne, una artista de feria que pretender ser clarividente.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenusElectrica/Es/P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenusElectrica/Es/Header_Movie_details_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenusElectrica/Es/6ac6a47e3b918-venus-electrica.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033762', 'Rocky - 50 Aniversario ', 'rocky-50-aniversario', 'A', 'DRAMA', 119, 'Rocky nos lleva hasta los barrios marginales de Filadelfia. Allí, Rocky Balboa recauda las deudas impagadas para Tony Gazzo, un usurero, y combate de vez en cuando, tan solo por un puñado de dólares, en combates de boxeo con el apodo de "El Potro Italiano". Desgraciadamente su antiguo entrenador, Mickey, le deja tirado. Su amigo Paulie, que trabaja en un almacén de congelados, anima a Rocky a salir con su hermana Adrian, una joven tímida que trabaja como vendedora en una tienda de mascotas. Durante ese tiempo, Apollo Creed, el campeón del mundo de boxeo en la categoría de pesos pesados, buscará un nuevo contrincante para volver a disputarse el título y su elección será Rocky.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Rocky50Aniversario/Es/Rocky50Aniversario_720x1022_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Rocky50Aniversario/Es/Rocky50Aniversario_1440x900_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Rocky50Aniversario/Es/6aea2f1631883-ROCKY_TLR_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033803', 'Los Juegos Del Hambre: Amanecer En La Cosecha', 'los-juegos-del-hambre-amanecer-en-la-cosecha', 'A', 'DRAMA, AVENTURA, ACCIÓN', 158, 'LOS JUEGOS DEL HAMBRE: AMANECER EN LA COSECHA revisitará el mundo de Panem 24 años antes de los eventos de Los Juegos del Hambre, comenzando en la mañana de la cosecha de los 50º Juegos del Hambre, también conocidos como el Segundo Vasallaje de los Veinticinco.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LosJuegosDelHambreAmanecerEnLaCosecha/Es/720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LosJuegosDelHambreAmanecerEnLaCosecha/Es/1440x900_57.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LosJuegosDelHambreAmanecerEnLaCosecha/Es/6a1f2ae3b8e0c-los-juegos-hambre.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033680', 'Menú Amanecer En La Cosecha', 'menu-tematico-los-juegos-del-hambre-amanecer-en-la-cosecha', 'A', 'DRAMA, AVENTURA, ACCIÓN', 180, 'Prepárate para regresar a Panem y vivir una experiencia inspirada en el universo de Los Juegos del Hambre en Cinépolis VIP, acompañada de un menú temático creado especialmente para adentrarte en esta nueva historia. Esta experiencia incluye tu entrada para disfrutar de la película en Cinépolis VIP y un menú especial: Entrada: jalapeño pops, crujientes bolitas de papa rellenas de queso y jalapeño, el snack perfecto para reunir fuerzas antes de enfrentarte a la arena. Plato fuerte: bagui de queso, pollo, tocino y miel, inspirado en uno de los alimentos más simbólicos y digno de acompañar a un vencedor. Postre: pay de fresa con un toque dulce para celebrar al tributo. Bebida 1: refrescante bebida sabor pitahaya y mango con bobas, un brebaje inspirado en los secretos para sobrevivir a los excesos. Bebida 2: ligeramente dulce sabor ptahaya, acompañada de fresa deshidratada, una bebida refrescante inspirada en el amanecer de una nueva cosecha. Ten en cuenta que esta experiencia es única, por lo que no se permiten cambios en alimentos o bebidas y no hay reembolsos una vez realizada la compra. Ninguna bebida incluye alcohol.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MenuTematicoAmanecerEnLaCosecha/Es/Poster_WEB_Desktop_720x1022px_HungerGames_copia_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MenuTematicoAmanecerEnLaCosecha/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_HungerGames_copia_copia_2_.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('grin-el-juego-de-la-ouija', 'Grin: El Juego De La Ouija', 'grin-el-juego-de-la-ouija', 'B15', 'DRAMA, TERROR, FANTASÍA', 81, 'Eve regresa a casa para reunirse con su familia, después de varios años de no verse. La reunión familiar también significa conocer a Lucien, la nueva pareja de su madre, un hombre que lleva consigo un extraño juego de mesa muy antiguo. Lo que comienza como una actividad para pasar el tiempo pronto se convierte en una pesadilla cuando el juego libera a GRIN, una entidad demoníaca con apariencia de bufón que comienza a perseguir a quienes esconden terribles secretos del pasado. GRIN no parece matar al azar. Ha venido a castigar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/GRIN_poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/GRIN_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/6ac7beb69c549-grin-juego-ouija.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033701', 'Fiesta Pagana', 'fiesta-pagana', 'A', 'BIOPIC', 128, 'A finales de los años ochenta, un grupo de jóvenes de barrio decide desafiar todas las reglas y perseguir un sueño que parecía imposible: fusionar la fuerza del heavy metal con la magia del folk celta. Lo que comenzó como la aventura de unos amigos acabó convirtiéndose en un fenómeno que revolucionó el rock en español y cambió sus vidas para siempre. FIESTA PAGÄNA es una película de ficción inspirada en la extraordinaria historia de Mägo de Oz. Comedia, musical, drama y ópera rock, explora lo que sucede cuando los sueños se cumplen y el éxito empieza a cobrar su precio. Sus canciones se convirtieron en la banda sonora de varias generaciones y en himnos que todavía hoy cantan millones de personas a ambos lados del Atlántico. Porque más de tres décadas después, la música y la leyenda de Mägo de Oz siguen más vivas que nunca. Inspirada en hechos reales. En cuáles depende de a qué miembro de la banda se le pregunte.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/6aea2f7b644ee-FIESTAPAGANA_TRAILER_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033246', 'Rammstein - Live in Mexico City', 'rammstein-live-in-mexico-city', 'B15', 'EN VIVO', 110, 'Rammstein - Live in Mexico City', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/Poster_WEB_Desktop_720x1022px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/6ac6a6a81fbf4-rammstein.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033682', 'Stray Kids World Tour <RUN IT> LIVE VIEWING', 'stray-kids-world-tour-run-it-live-viewing', 'A', 'CONCIERTO', 195, 'Por primera vez, Stray Kids presenta una transmisión especial en vivo de «Stray Kids World Tour » desde el Tokyo Dome en cines de todo el mundo. Fiel al título de la gira, refleja el impulso del grupo por adentrarse en mundos más grandes y subir a escenarios más audaces. Los ocho miembros (Bang Chan, Lee Know, Changbin, Hyunjin, HAN, Felix, Seungmin e I.N) desatan una energía imparable a través de coreografías explosivas y voces potentes, llevando la experiencia en vivo a su punto más álgido. Su presentación empieza con «Hall of Fame», una canción que expresa la ambición de Stray Kids de escribir su propia historia, trazando su crecimiento musical desde el principio hasta donde están ahora. La producción se enriquece aún más con montajes escénicos dinámicos, toques de espectáculos tradicionales coreanos y una iluminación láser espectacular, todo diseñado para que el público —tanto en el estadio como en el cine— se ponga de pie, cante, baile y celebre junto con los artistas. Grabado en vivo desde Tokio y transmitido a cines de todo el mundo, este evento de proyección en vivo te permite a ti, como parte de STAY, disfrutar de la magnitud, el espectáculo y la energía pura del show en vivo de Stray Kids —todos juntos, en la pantalla grande.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/6ad112c94c215-Stray_Kids_World_Tour_30_Trailer_SPANISH_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033788', 'Entrega Al Límite', 'entrega-al-limite', 'B15', 'COMEDIA, ACCIÓN', 99, 'El mensajero Frank transporta un órgano a un joven receptor que puede salvarle la vida. La misión se vuelve peligrosa cuando un despiadado jefe del crimen busca la posesión del órgano a cualquier precio.​', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/Poster_720x1022_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/Header_Movie_Details_1440x900_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/6ac57f4a99209-entrega-limite.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033223', 'Ebenezer: Los Fantasmas De Navidad', 'ebenezer-los-fantasmas-de-navidad', 'B15', 'DRAMA, FANTASÍA', 115, 'Este noviembre Johnny Depp será Ebenezer Scrooge. El nombre ya lo conoces, pero la historia no. Del director Ti West, EBENEZER también cuenta con la participación de Rupert Grint, Andrea Riseborough, Sam Claflin, Daisy Ridley, Arthur Conti, Ellie Bamber, Henry Lloyd-Hughes, Charlie Murphy, junto a Tramell Tillman e Ian McKellen.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EbenezerElFantasmaDeNavidad/Es/EBZR_Desktop_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EbenezerElFantasmaDeNavidad/Es/EBZR_Desktop_Header_Movie_Details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EbenezerElFantasmaDeNavidad/Es/6acfddfd937f2-EBENEZER_ITR-E_LAS_SUB_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033155', 'Sensatez Y Sentimiento', 'sensatez-y-sentimiento', 'A', 'ROMANCE, DRAMA', 132, 'Basada en la novela de Jane Austen, Sentido y sensibilidad es la historia de las hermanas Elinor y Marianne Dashwood y su viaje para encontrar el amor y superar el desamor y la pobreza con gracia y madurez.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/15_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/6aa1c2d660ad1-sensatez-sentimiento.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033129', 'El Corazón De La Bestia', 'el-corazon-de-la-bestia', 'B', 'DRAMA, ACCIÓN', 101, 'Tras un aterrador accidente aéreo, el oficial de Fuerzas Especiales James Belmont (Brad Pitt) y su perro de combate, Odin, quedan varados en lo profundo de la naturaleza salvaje de Alaska. Juntos, se ven obligados a librar una brutal lucha por la supervivencia contra los elementos. Del aclamado cineasta David Ayer, Heart of the Beast es un intenso thriller de aventura que explora el vínculo irrompible entre un hombre y su mejor amigo mientras enfrentan su mayor batalla hasta ahora.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/HOBT_A_1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/6a44173cccd16-HOTB_W8_1366x770_1.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033766', 'The Babadook', 'el-babadoock', 'A', 'TERROR', 94, 'Amelia es una madre viuda que lucha por sacar adelante a su hijo Samuel, un niño tan inteligente como problemático. Cuando ambos descubren un inquietante libro infantil sobre una misteriosa criatura llamada El Babadook, una presencia oscura comienza a invadir su hogar y sus vidas. A medida que el miedo se apodera de ellos, Amelia deberá enfrentarse a una aterradora fuerza que parece alimentarse de sus peores pensamientos y emociones. Pero pronto descubrirá que algunos monstruos no habitan bajo la cama... sino en los rincones más profundos de nuestra mente.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheBabadook/Es/ElBabadook_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheBabadook/Es/ElBabadook_1440x900.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheBabadook/Es/6aea2f4dea769-Babadook_MQC_Trailer_Sub_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033937', 'Re Los Juegos del Hambre', 're-los-juegos-del-hambre', 'B', 'DRAMA, AVENTURA, ACCIÓN', 145, 'Katniss Everdeen toma voluntariamente el lugar de su hermana menor en los Juegos del Hambre: una competencia televisada en la que dos adolescentes de cada uno de los doce distritos de Panem son elegidos al azar para luchar hasta la muerte.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Relosjuegosdelhambre/Es/720x1022_27.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Relosjuegosdelhambre/Es/1400x900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
