INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033740', 'Campeón Gabacho', 'campeon-gabacho', 'B15', 'ACCIÓN', 108, 'Liborio llega a Estados Unidos con los bolsillos vacíos y las ganas de comerse al mundo. Buscando cómo salir adelante, termina en un ring de boxeo, donde descubre que su talento para aguantar golpes puede cambiarle la vida. Entre peleas, enredos y un amor que le mueve el piso, este mexicano se abrirá camino con ingenio y mucho corazón, dispuesto a demostrar que puede llegar lejos, aunque nadie crea en él.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/CG_DESKTOP_P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/CG_DESKTOP_Header_flujo_de_compra_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/6acff69b5e51b-campeon-gabacho.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033791', 'Blue Lock', 'blue-lock', 'A', 'DRAMA, SUSPENSO, ACCIÓN', 127, '300 jugadores de fútbol compiten en despiadadas pruebas en un centro de entrenamiento secreto, donde solo uno se convertirá en el mejor delantero del mundo y los eliminados son expulsados de la selección nacional de Japón.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/6acfe11089a2a-blue-lock.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('el-desconocido-del-gran-arco', 'El Desconocido Del Gran Arco', 'el-desconocido-del-gran-arco', 'B', 'DRAMA', 104, 'En 1983, el presidente François Mitterrand convocó el mayor concurso de arquitectura de la historia. Su objetivo: erigir un nuevo monumento en París que al mismo tiempo se convierta en la insignia de su mandato. Para sorpresa de todos, el ganador es un absoluto desconocido: Johan Otto von Spreckelsen, un profesor de arquitectura de Copenhague quien, sin esperarlo, se convirtió en el centro de todas las miradas al quedar a cargo de la obra más ambiciosa del momento: el Arco de la Defensa de París. El filme parte de la psicología del protagonista y las adversidades que enfrenta en su proyecto para hablar de temas complejos como el enfrentamiento entre idealismo y poder político, la ética profesional y las barreras que el poder impone a la creación artística.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/Header_Movie_details_1440x900_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/6ac7bbe62e85a-desconocido-gran-arco.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('everest-la-otra-cara', 'Everest: La Otra Cara', 'everest-la-otra-cara', 'A', 'DOCUMENTAL, DEPORTE', 115, 'Los esquiadores de alta montaña de élite Jim Morrison e Hilaree Nelson se enamoraron profundamente mientras alcanzaban la cima de su deporte. Su determinación se convirtió en un sueño compartido: escalar y esquiar por la cara norte directa del Everest, el camino más difícil y peligroso de la montaña y la ruta de esquí más codiciada del mundo. Miles de personas han coronado la montaña por la cresta sureste de Nepal, pero solo un puñado ha llegado a la cima por esta ruta y nadie ha conseguido descender esquiando con éxito. Ya conocidos por sus extraordinarias hazañas en la montaña y acostumbrados a las pérdidas, Morrison y Nelson lo apuestan todo a este desalentador reto.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/14_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/6ad1038729a8c-everest-otra-cara.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033376', 'Street Fighter', 'street-fighter', 'B', 'DRAMA, ACCIÓN', 119, 'Ambientada en 1993, los distanciados luchadores callejeros Ryu (Andrew Koji) y Ken Masters (Noah Centineo) se ven obligados a volver al combate cuando la misteriosa Chun-Li (Callina Liang) los recluta para el próximo Torneo Mundial de Luchadores: un brutal enfrentamiento de puños, destino y furia. Pero detrás de esta batalla real se esconde una conspiración mortal que los obliga a enfrentarse entre sí y a los demonios de su pasado. Y si no lo hacen, ¡GAME OVER!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/6a870c70166c5-street-fighter.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ciudad-de-muertos', 'Ciudad De Muertos', 'ciudad-de-muertos', 'B15', 'THRILLER', 102, 'Inspirada en la obra de Enrique Metinides, Ciudad de Muertos sigue a Enrique, un fotógrafo de nota roja en la Ciudad de México de los años 50, cuya obsesión por documentar la tragedia comienza a desdibujar los límites entre la realidad y la imaginación. Tras un terremoto que deja la ciudad en ruinas, empieza a experimentar apariciones extrañas, visiones inquietantes y encuentros con un hombre desfigurado que parece seguirlo. En medio del caos, irrumpe Yola, una niña curiosa y enigmática que lo acompaña en un recorrido donde la frontera entre los vivos y los muertos se vuelve cada vez más difusa.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/720x1022_27.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/DESKTOP_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/6abc4aa02b3b9-ciudad-muertos.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('lecciones-de-otono', 'Lecciones De Otoño', 'lecciones-de-otono', 'B', 'DRAMA', 85, 'En el otoño de su vida, don Alfonso Aldaz Iglesias (Miguel Pizarro) espera con ansias el final de sus días en su piso de Madrid. Sin embargo, quien llama a su puerta no es la muerte, sino un inesperado visitante que le ofrecerá un destino diferente al anhelado. Una película esperanzadora basada en la exitosa novela de Iván Eduardo Lópezcampos que nos invita a descubrir detalles de la vida que solemos pasar por alto y nos lleva a replantearnos cómo nos relacionamos con nuestros mayores. Una apuesta valiente por un cine con valores; una historia que nos inspira a ser más humanos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/19_Poster_720x1022_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/14_Header_Movie_details_1440x90014_Header_Movie_details_1440x900_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/6adba974999e4-lecciones-de-otono.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033073', 'El Poder De La Red', 'el-poder-de-la-red', 'B', 'DRAMA, THRILLER', 112, 'Como complemento de la exitosa película La red social, el guion original de Sorkin se basa en los hechos que dieron origen al impactante reportaje del Wall Street Journal, Los archivos de Facebook. La película se inspira en la historia real de cómo Frances Haugen (Madison), una joven ingeniera de Facebook, recluta a Jeff Horwitz (White), un reportero del Wall Street Journal, para emprender un peligroso viaje que termina por revelar los secretos mejor guardados de la red social.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/TSR_1440x900_V1_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/6aa16953e44ac-poder-red.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033358', 'Madre Siniestra', 'madre-siniestra', 'B', 'HORROR PSICOLÓGICO', 93, 'Bela, una niña de 8 años que vive en un hogar con problemas matrimoniales, se enfrenta a una entidad siniestra que sale de su clóset. La presencia, a quien ella llama "Otra Mamá", se vuelve cada vez más amenazante para ella y su familia.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/20_Po_ster_720x1022px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/15_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/6a8f6e14b4a58-madre-siniestra.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('verity-la-sombra-de-un-engano', 'Verity: La Sombra De Un Engaño', 'verity-la-sombra-de-un-engano', 'B15', 'SUSPENSO', 117, 'Basada en la exitosa novela de Colleen Hoover, este seductor thriller psicológico sigue a la reconocida autora Verity Crawford (Anne Hathaway) y a Lowen Ashleigh (Dakota Johnson), una escritora en apuros que se muda a la remota mansión Crawford para escribir como ghostwriter para Verity. Después de que Lowen descubre lo que parecen ser las escalofriantes notas autobiográficas de Verity, lucha con las perturbadoras y retorcidas confesiones sobre el esposo de Verity, Jeremy (Josh Hartnett), y le resulta difícil separar la ficción de la realidad, la manipulación de la atracción, y la oportunidad de la obsesión.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_HeaderMovieDetails_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/6a91ece8785e6-verity.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('amarte', 'Amarte', 'amarte', 'A', 'COMEDIA, ROMANCE', 96, 'Él vive en su propio universo. Ella es una famosa estrella de telenovelas que necesita desaparecer del suyo. Cuando se encuentran por accidente, lo que parece una mala idea se convierte en una escapada tan absurda como irresistible. Mientras huyen de la prensa, entre situaciones cada vez más fuera de lugar, momentos delirantes y una conexión que nadie vio venir, ambos descubren que escapar de la realidad puede ser mucho más divertido… y peligrosamente irresistible para el corazón. Pero cuando el mundo real vuelve a alcanzarlos, deberán decidir si ese encuentro fue sólo una fantasía perfecta o si vale la pena arriesgarse a vivir algo real.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/6a750336bcc28-amarte.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033577', 'La Caída De La Ballena', 'la-caida-de-la-ballena', 'B', 'SUSPENSO', 106, 'Tras la muerte de su padre (Josh Brolin), Jay Gardiner (Austin Abrams) se sumerge en la costa central de California en busca de sus restos, pero es tragado por un enorme cachalote. Atrapado en el interior del animal y con solo una hora de oxígeno restante, Jay descubre que las lecciones que su padre le enseñó podrían ser la clave para sobrevivir y escapar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/6abd9611801cc-whalefall.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033697', 'El Laberinto Del Fauno', 'el-laberinto-del-fauno', 'B15', 'DRAMA, FANTASÍA', 118, 'Con motivo de su 20.º aniversario, El laberinto del fauno, del visionario cineasta Guillermo del Toro, es una cinta de fantasía oscura ganadora del Premio de la Academia®, ambientada en la España de 1944. Mientras las fuerzas fascistas estrechan su control tras la Guerra Civil española, la joven Ofelia (Ivana Baquero) es llevada a un remoto puesto militar bajo el mando de su cruel padrastro (Sergi López). En medio de la brutalidad de la guerra, Ofelia descubre un laberinto oculto y se encuentra con un misterioso fauno que afirma que ella es una princesa perdida. Para recuperar su trono, deberá completar tres peligrosas pruebas que pondrán a prueba su valentía y su espíritu. A medida que la realidad y la fantasía se entrelazan, el viaje de Ofelia se convierte en una poderosa exploración de la inocencia, la resistencia y el poder perdurable de la imaginación frente a una oscuridad inimaginable.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/Poster_WEB_Desktop_720x1022px_43__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_45__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/6ac6a503c38ac-el-laberinto-fauno.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tierra-de-mi-padre', 'Tierra De Mi Padre', 'tierra-de-mi-padre', 'B', 'DRAMA', 82, 'En el apogeo de la Guerra Fría, Patria se centra en la relación entre el escritor Thomas Mann y su hija Erika —actriz, escritora y conductora de rally— mientras se embarcan en un viaje por carretera en un crucero Buick negro a través de una Alemania en ruinas.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/1440x900_55.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/6a7cfbde56777-Fatherland.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('resident-evil-noche-cero', 'Resident Evil: Noche Cero', 'resident-evil-noche-cero', 'B15', 'TERROR, ACCIÓN', 94, 'De la mente del visionario cineasta Zach Cregger (Weapons, Barbarian) llega una emocionante —y aterradora— reinvención de la franquicia Resident Evil. En una historia completamente nueva, Resident Evil sigue a Bryan (Austin Abrams), un mensajero médico que, sin saberlo, se ve envuelto en una carrera por la supervivencia llena de acción y sin tregua cuando una noche fatídica y espantosa se convierte en un caos a su alrededor.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/6a7cfa8bd1eab-RESIDENTEVIL.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('digger', 'Digger', 'digger', 'B15', 'COMEDIA, DRAMA', 129, 'El cineasta ganador del Oscar Alejandro G. Iñárritu regresa con su película original DIGGER, protagonizada por Tom Cruise en el papel principal. El hombre más poderoso del mundo emprende una frenética misión para demostrar que es el salvador de la humanidad antes de que el desastre que ha desatado destruya todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/720x1022_28.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/HMD_1440X900_8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/6a9883ec5b261-digger.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('hope-el-primer-impacto', 'Hope: El Primer Impacto ', 'hope-el-primer-impacto', 'B15', 'ACCIÓN', 157, 'Un misterioso descubrimiento se realiza en las afueras de la remota ciudad del puerto. Los residentes se encuentran en una lucha desesperada por la supervivencia contra algo que nunca antes habían encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_720_x_1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_1440_x_900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/6aa87c469b3df-hope-el-primer-impacto.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-isla-de-las-munecas', 'La Isla De Las Muñecas', 'la-isla-de-las-munecas', 'B', 'TERROR', 80, 'Cuenta la leyenda de este lugar, que cerca de las chinampas de Don Julián una joven se ahogo entre los lirios y ahi su cuerpo fue encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Header_Movie_details_1440X900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/6ab437a2ae697-isla-munecas.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033961', 'Re Los Juegos del Hambre: Balada de Pájaros Cantores y Serpientes', 'los-juegos-del-hambre-balada-de-pajaros-cantores-y-serpientes', 'B', 'DRAMA, CIENCIA FICCIÓN, ACCIÓN Y AVENTURA', 160, 'Ambientada en un Panem postapocalíptico, nos traslada varias décadas antes del comienzo de las aventuras de Katniss Everdeen. El joven Coriolanus Snow será el mentor de Lucy Gray Baird, la chica elegida para ser homenajeada del empobrecido Distrito 12. La joven sorprenderá a todos cantando en la ceremonia de apertura de los Décimos Juegos del Hambre en los que Snow intentará aprovecharse de su talento y encanto para sobrevivir', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambrebaladadepajaroscantoresyserpientes/Es/720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambrebaladadepajaroscantoresyserpientes/Es/1440X900_8.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tu-nombre', 'Tu Nombre', 'tu-nombre', 'A', 'ANIMACIÓN', 107, 'Mitsuha, una adolescente que vive en un pequeño pueblo de Japón, sueña con escapar de su vida cotidiana y conocer una ciudad llena de oportunidades. Taki, un joven que vive en Tokio, lleva una vida completamente diferente. Un día, ambos comienzan a intercambiar cuerpos misteriosamente mientras duermen, despertando cada uno en la vida del otro. Aunque al principio intentan comprender y controlar este extraño fenómeno, poco a poco desarrollan un vínculo especial a través de mensajes y recuerdos. Sin embargo, cuando el intercambio desaparece inesperadamente, Taki emprende una búsqueda para encontrar a Mitsuha y descubrir la verdad detrás de su conexión, enfrentándose a un misterio que trasciende el tiempo y el espacio. Revive esta historia 10 años despues de su estreno en salas de cine.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/Poster_WEB_Desktop_720x1022px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/6ac6a52bbd523-your-name.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033943', 'Re Los Juegos del Hambre: En Llamas ', 'los-juegos-del-hambre-en-llamas', 'B', 'DRAMA, CIENCIA FICCIÓN, ACCIÓN Y AVENTURA', 148, 'Katniss Everdeen y Peeta Mellark se convierten en objetivo del Capitol cuando su victoria en los 74 Juegos de Hambre da comienzo a una rebelión en los distritos de Panem.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambreenllamas/Es/720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambreenllamas/Es/1440X900_8.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('cristiada', 'Cristiada', 'cristiada', 'B', 'DRAMA', 140, 'En el marco de los 100 años de la Guerra Cristera, hoy presentamos por primera vez en español la película Cristiada. Esta obra es mucho más que una crónica histórica de 1926 a 1929; nos cuenta la historia de un grupo apasionado de hombres y mujeres que deciden arriesgarlo todo por su familia, por el futuro de su país y, de manera fundamental, por defender su fe. Es, además, un poderoso relato sobre la transformación: seguimos los pasos de un líder inicialmente escéptico que, guiado por la convicción del joven José Sánchez del Río, termina al mando de todo el ejército cristero.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/Poster_WEB_Desktop_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_5.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033949', 'Re Los Juegos del Hambre: Sinsajo - Parte 1', 'los-juegos-del-hambre-sinsajo-parte-1', 'B', 'DRAMA, CIENCIA FICCIÓN, ACCIÓN Y AVENTURA', 125, 'Katniss Everdeen se encuentra en el Distrito 13 después de destrozar los Juegos para siempre. Bajo el liderazgo de la comandante Coin y el consejo de sus amigos más leales, Katniss extiende sus alas mientras lucha por salvar a Peeta Mellark y a una nación alentada por su valentía.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegodelhambresinsajoParte1/Es/720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegodelhambresinsajoParte1/Es/1440X900_8.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033955', 'Re Los Juegos del Hambre: Sinsajo - Parte 2', 'los-juegos-del-hambre-sinsajo-parte-2', 'B', 'DRAMA, CIENCIA FICCIÓN, ACCIÓN Y AVENTURA', 139, 'La última entrega de ''Los Juegos del Hambre'' nos muestra a una nación en guerra, en la que Katniss se enfrenta con uñas y dientes al presidente Snow (Donald Sutherland). Con la ayuda de algunos amigos, entre ellos Gale (Liam Hemsworth), Finnick (Sam Claflin) y Peeta (Josh Hutcherson), arriesgará la vida para salir del Distrito 13 y eliminar al presidente Snow.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambresinsajoParte2/Es/720_x_1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ReLosjuegosdelhambresinsajoParte2/Es/1400_x_900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('coyote-vs-acme', 'Coyote Vs Acme', 'coyote-vs-acme', 'A', 'COMEDIA, AVENTURA, LIVE ACTION ', 103, 'Tras décadas de explosiones por productos defectuosos y cansado de caídas al abismo, Wile E. Coyote decide demandar a ACME. El coyote más emblemático junto con el universo de los Looney Toones, está decidido a desmantelar un imperio y enfrentar a su implacable CEO (John Cena). Esta batalla, destruirá a una leyenda... o a una corporación. La película que ACME NO QUIERE QUE VEAS.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/6a442a872bb67-CVA_Trailer_Zima_Dob_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033768', 'La Posesión', 'posesion', 'B15', 'TERROR', 127, 'Berlín, antes de la caída de El Muro. Cuando Marc regresa de un viaje encuentra a su esposa Anna cambiada, muy nerviosa y perturbada. Al fin, le confiesa que tiene una aventura con otro hombre y lo abandona. Marc cae en una terrible depresión que lo lleva casi al borde de la locura. Poco después Marc se entera de que su mujer también ha abandonado a su amante, y la verdad sobre la aventura secreta de Anna se revelará de manera monstruosa.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Posesion/Es/Poster_WEB_Desktop_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Posesion/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_5.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('avengers-endgame-bonus', 'Avengers: Endgame Bonus', 'avengers-endgame-bonus', 'B', 'ACCIÓN, CIENCIA FICCIÓN', 191, 'Tras los devastadores sucesos de Avengers: Infinity War, el universo está en ruinas pero de los que quedan, los Avengers se unirán una vez más para deshacer la destrucción de Thanos y restaurar el orden del mundo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/6a95930ba5241-avengers-endgame-encore.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('palm-el-guardian', 'PALM El Guardián', 'palm-el-guardian', 'B', 'DRAMA', 116, '1° PALMAR Film Festival. El Guardián. Basilio es contratado para cuidar una playa desierta en Baja California. En este paraíso, en el que parece que no pasa nada, ocurren muchas cosas y algunas de ellas ilegales. Basilio, que es un hombre de normas morales férreas, busca hacer lo correcto. Sin embargo, lo que él cree que es hacer lo correcto le puede jugar en contra en una comunidad que apenas conoce.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMElGuardian/Es/guardian_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMElGuardian/Es/_1440X900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('palm-volar-y-otros-deseos', 'PALM Volar y Otros Deseos', 'palm-volar-y-otros-deseos', 'B', 'DRAMA', 103, '1° PALMAR Film Festival. Volar y Otros Deseos. Silvia es una mujer en sus sesentas inmersa en su rutina como madre de una familia tradicional, hasta que llega Varenka, quien hará que se cuestione su vida y su sexualidad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMVolaryOtrosDeseos/Es/volar_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMVolaryOtrosDeseos/Es/_1440X900_copia.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-la-mancha', 'FMORB La Mancha', 'fmorb-la-mancha', 'C', 'TERROR', 72, '19° Mórbido Film Fest. La Mancha. En un parque de diversiones, un grupo de niños y adolescentes quedan atrapados en una maldición que los conecta con un mundo paralelo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBLaMancha/Es/La_Mancha_720x1022_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBLaMancha/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-bad-lieutenant-tokyo', 'FMORB Bad Lieutenant: Tokyo', 'fmorb-bad-lieutenant-tokyo', 'C', 'THRILLER', 108, '19° Mórbido Film Fest. Bad Lieutenant: Tokyo. Un policía de Tokio, adicto al juego, queda envuelto en una investigación cuando una misteriosa agente del FBI llega a Japón tras la desaparición de la hija de un político.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBadLieutenantTokyo/Es/Bad_Lieutenant_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBadLieutenantTokyo/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-bloque-de-cortometrajes', 'FMORB Cinema Recomposed - Silent Monsters and more!', 'fmorb-bloque-de-cortometrajes', 'C', 'ANIMACIÓN', 112, '19° Mórbido Film Festival. Bloque de Cortometrajes. Bloque de cortometrajes seleccionados por Mórbido Fest 2026 que reúnen lo más reciente del cine fantástico y de horror hecho por nuevas voces de México, América Latina y el mundo. Monstruos, fantasmas, cuerpos que mutan y pesadillas muy cercanas a lo cotidiano: el formato corto como laboratorio donde el género se reinventa sin pedir permiso.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBCinemaRecomposedSilentMonstersandmore/Es/cinema_recomposed_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBCinemaRecomposedSilentMonstersandmore/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-mi-amigo-el-sol', 'FMORB Mi Amigo el Sol', 'fmorb-mi-amigo-el-sol', 'A', 'ANIMACIÓN', 97, '19° Mórbido Film Fest. Mi Amigo el Sol. Diego y su hija Xóchitl venden pinturas de mitología mexicana en la Ciudad de México. Cuando el mural de Xóchitl da vida a una criatura mítica, es llevada al mundo de los dioses antiguos. Diego debe navegar por los mitos para salvarla.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBMiAmigoelSol/Es/Mi_Amigo_el_Sol_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBMiAmigoelSol/Es/1440x900_68.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-infirmary', 'FMORB Infirmary', 'fmorb-infirmary', 'C', 'TERROR', 102, '19° Mórbido Film Fest. Infirmary. Material recuperado de una cámara corporal revela la primera noche de un joven guardia de seguridad dentro de un hospital abandonado, donde una serie de incidentes perturbadores e inexplicables y un siniestro intruso hacen que su turno se salga de control.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBInfirmary/Es/Infirmary_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBInfirmary/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-quince', 'FMORB Quince', 'fmorb-quince', 'C', 'TERROR', 87, '19° Mórbido Film Festival. Quince. Dos mejores amigas planean la mejor fiesta de quince años. Cuando una de ellas queda embarazada de una criatura monstruosa, el embarazo la convierte en un inesperado ícono social de la escuela, la amistad se fractura y la celebración soñada se vuelve peligrosamente surreal.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBQuince/Es/Delivery_70x100_Fest_Quince_27Mar_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBQuince/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-victorian-psycho', 'FMORB Victorian Psycho', 'fmorb-victorian-psycho', 'C', 'TERROR, THRILLER', 90, '19° Mórbido Film Festival. Victorian Psycho. Inglaterra, 1858. Winifred Notty, una institutriz poco convencional, llega a Ensor House, una remota mansión gótica. Poco después de su llegada, miembros del servicio comienzan a desaparecer misteriosamente y los dueños de la casa empiezan a sospechar que hay algo siniestro en su nueva empleada.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBVictorianPsycho/Es/La_Psicopata_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBVictorianPsycho/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-i-love-paris', 'FMORB I Love Paris', 'fmorb-i-love-paris', 'C', 'COMEDIA, TERROR', 120, '19° Mórbido Film Fest. I Love Paris. Después de ser mordida por una vampira, una joven cantante parisina persigue el estrellato a costa de su alma, en un falso documental donde la fama y la sed de sangre resultan perfectamente compatibles.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBILoveParis/Es/I_Love_Paris_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBILoveParis/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-ken-russells-the-devils', 'FMORB Ken Russell''s The Devils', 'fmorb-ken-russells-the-devils', 'C', 'TERROR', 114, '19° Mórbido Film Fest. Ken Russell''s The Devils. Francia, 1634. Urbain Grandier, un carismático y libertino sacerdote de Loudun, se convierte en el blanco de una conspiración política y religiosa cuando una monja reprimida, obsesionada con él, lo acusa de brujería tras una ola de supuestas posesiones demoníacas en el convento. Un juicio fanático lo condena a la hoguera.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBKenRussellsTheDevils/Es/The_Devils_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBKenRussellsTheDevils/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-sicko', 'FMORB Sicko', 'fmorb-sicko', 'C', 'COMEDIA, THRILLER', 102, '19° Mórbido Film Fest. Sicko. En Almaty, una pareja ahogada en deudas finge una enfermedad terminal y lanza una campaña de crowdfunding para salir adelante. Su éxito viral llama la atención de criminales y el plan se sale peligrosamente de control, desembocando en violencia y caos: un retrato feroz de la precariedad económica contemporánea.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSicko/Es/Sicko_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSicko/Es/1440x900_67.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('vertigo-2-punto-muerto', 'Vértigo 2: Punto Muerto', 'vertigo-2-punto-muerto', 'B', 'SUSPENSO', 98, 'Durante una peligrosa escalada en el monte Kwan, en Tailandia, dos escaladoras quedan atrapadas a miles de metros sobre el suelo, donde las alturas vertiginosas, la exposición extrema y las pocas probabilidades de sobrevivir convierten cada instante en una lucha por mantenerse con vida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/6a98833208c7b-vertigo-2.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('queen-budapest', 'Queen Budapest', 'queen-budapest', 'A', 'CONCIERTO', 97, 'El 27 de julio de 1986, Queen se presentó en el Népstadion de Budapest frente a 80,000 fans exaltadísimos; un concierto que ahora está magníficamente remasterizado en 4K con una nueva y potente mezcla de audio.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/QueenBudapest/Es/Poster_WEB_Desktop_720x1022px_28__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/QueenBudapest/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_29__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/QueenBudapest/Es/6a94b410aa2db-queen-budapest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tadeo-el-explorador-y-la-lampara-maravillosa', 'Tadeo El Explorador Y La Lámpara Maravillosa', 'tadeo-el-explorador-y-la-lampara-maravillosa', 'AA', 'ANIMACIÓN, FAMILIAR', 94, 'Tadeo y Sara son ahora padres de Olimpia (Oli), una adorable e intrépida niña de dos años. Y Momia no lleva nada bien haber dejado de ser el centro de atención. Mientras están de vacaciones en Londres, Sara sigue la pista de un objeto único: la lámpara maravillosa de Las mil y una noches. Y Momia, lleno de celos, pide un deseo: viajar en el tiempo hasta el momento en que era joven y todos le querían. Tadeo y Sara tienen que unir fuerzas para evitar que Momia cambie el curso de la historia y traer al grupo (Jeff, Belzoni y Ramona incluidos) de vuelta a casa. Esta nueva aventura los llevará a cruzar el Océano Atlántico desde la mítica ciudad perdida de Paititi hasta Grecia, y de allí a lo más profundo de Oriente Medio, hasta la misma cueva de Ali Babá y los Cuarenta ladrones.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_6_720x1022_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_2_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/6a4d6b1d28bec-tadeo-lampara-maravillosa.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('atrapelo-quien-pueda', 'Atrápelo Quien Pueda', 'atrapelo-quien-pueda', 'A', 'COMEDIA ROMÁNTICA', 85, 'Después de años dedicado por completo a su trabajo y a la crianza de su hija, Diego, un padre viudo de 45 años, vuelve al mundo de las citas empujado por Marina, su hija de 11. Entre intentos fallidos, consejos poco útiles y encuentros cada vez más desastrosos, Diego descubrirá que abrirse nuevamente al amor puede ser mucho más difícil —y mucho más divertido— de lo que imaginaba. Sobre todo cuando la persona que empieza a cambiarlo todo resulta ser Lucía, su nueva vecina, una actriz carismática con quien parecía tener todo menos química.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AtrapeloQuienPueda/Es/AQP_DESKTOP_P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AtrapeloQuienPueda/Es/AQP_Header_flujo_de_compra_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AtrapeloQuienPueda/Es/6ae374ebbd274-atrapelo-quien-pueda.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('como-robar-un-banco', 'Cómo Robar Un Banco', 'como-robar-un-banco', 'B15', 'THRILLER, ACCIÓN, CRIMEN', 121, 'En "Cómo Robar Un Banco", una banda de ladrones expertos en redes sociales transmite en vivo sus audaces robos bancarios, sin darse cuenta de que la fama viral que están ganando los ha puesto en la mira de un veterano agente del FBI y una brillante ingeniera de software. A pesar de que este dúo fuera de lo común les sigue la pista cada vez más de cerca, la organización criminal lleva sus límites al extremo, arriesgándolo todo por sus ideales y por el golpe más ambicioso de sus vidas hasta ahora.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ComoRobarUnBanco/Es/HTRB_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ComoRobarUnBanco/Es/HTRB_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ComoRobarUnBanco/Es/6adbace2c81ad-como-robar-un-banco.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('el-caso-de-los-milagros', 'El Caso de los Milagros', 'el-caso-de-los-milagros', 'A', 'DOCUMENTAL', 90, 'Basado en el libro The Case for Miracles de Lee Strobel, El Caso de los Milagros emprende un viaje por la histórica Ruta 66 para explorar historias reales y casos documentados de personas que aseguran haber experimentado milagros. Acompañado por testimonios, investigaciones y perspectivas de expertos, Lee Strobel examina la evidencia detrás de estos acontecimientos extraordinarios mientras busca responder una pregunta que ha intrigado a la humanidad durante siglos: ¿siguen ocurriendo milagros hoy en día?. Desde experiencias que desafían toda explicación hasta momentos en los que el milagro parece ausente, la película invita al espectador a cuestionar lo que cree posible y a acompañar a Strobel en una búsqueda de respuestas que puede transformar la manera en que entendemos la fe, la ciencia y lo extraordinario.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCasodelosMilagros/Es/ElCasoDeLosMilagros_poster_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCasodelosMilagros/Es/ElCasoDeLosMilagros_1440x900_copia_2_.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('gail-daughtry-y-la-lista-de-famosos', 'Gail Daughtry Y La Lista De Famosos', 'gail-daughtry-y-la-lista-de-famosos', 'B15', 'COMEDIA', 94, 'En el encantador pueblo de Willowbrook, Kansas, la peluquera Gail Daughtry está comprometida con su devoto novio de secundaria, Tom. Su vida da un giro cuando un viaje a una firma de libros hace que Tom conozca –y se acueste– con su propio “pase de celebridad”. Conmocionada por la traición, Gail se une impulsivamente a su amigo Otto en un viaje a Los Ángeles, donde una psíquica la convence de que la única forma de salvar su matrimonio es “igualar las cosas” con su propio pase de celebridad: Jon Hamm. Así comienza un viaje épico por Tinseltown, mientras Gail y Otto se unen con un asistente de agencia de talentos, un paparazzi y el actor John Slattery, todos en la búsqueda de Hamm. En el camino, se topan con celebridades y son perseguidos por un grupo de asesinos italianos mientras se acercan cada vez más a encontrar a la esquiva estrella.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GailDaughtryYLaListaDeFamosos/Es/720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GailDaughtryYLaListaDeFamosos/Es/1440X900_14-2.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('mi-robot-y-yo', 'Mi Robot Y Yo', 'mi-robot-y-yo', 'A', 'ANIMACIÓN', 102, 'Cuando Celeste, una joven astronauta, parte en su primera misión al espacio, dejando atrás a su Robot guardían, que la crió como a una hija. Mientras ella lucha por sobrevivir en un planeta lejano, Él enfrenta la soledad en la Tierra, aferrándose a los recuerdos que los unen. A través del tiempo, la distancia y las estrellas, ambos deberán encontrar la manera de volver a casa.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MiRobotYYo/Es/Poster_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MiRobotYYo/Es/Header_movie_details_1440x900px_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MiRobotYYo/Es/6adbabf1e415a-mi-robot-y-yo.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('petardos-y-magnolias', 'Petardos Y Magnolias', 'petardos-y-magnolias', 'B', 'DRAMA', 100, 'Vera, adolescente de 18 años y una de las mejores jugadoras de fútbol de la Prepa 8 de la UNAM, está comprometida a volverse una estrella del fútbol femenil, a pesar de los deseos de su padre en que abandone sus sueños. Un día conoce a Alan, que es parte del grupo de choque de su preparatoria. Ella se enamora de él, no sin antes darse cuenta que está a punto de entrar a un mundo muy peligroso. Ambos descubrirán que el amor tiene muchos matices y sobre todo consecuencias.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PetardosYMagnolias/Es/P_M_Poster_720x1022_DESKTOP.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PetardosYMagnolias/Es/P_M_Headermoviedetails_1400x900_DESKTOP.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PetardosYMagnolias/Es/6ae382fc17263-petardos-y-magnolias.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
